def resolve_call_silence_timeout(
    channel_silence_timeout: Optional[float],
    agent_silence_timeout: Optional[float],
) -> float:
    """Prefer the channel timeout, then the agent timeout, then the default.

    The channel value is the voice-channel ``silence_timeout``. The agent value
    comes from the loaded processor and is ``None`` for CALM.
    """
    if channel_silence_timeout is not None:
        return float(channel_silence_timeout)
    if agent_silence_timeout is not None:
        return float(agent_silence_timeout)
    return GLOBAL_SILENCE_TIMEOUT_DEFAULT_VALUE


# define constants for the voice channel
DEFAULT_MIN_DELAY_BETWEEN_BOT_MESSAGES_SECONDS = 1
DEFAULT_MIN_DELAY_AFTER_FILLER_BOT_MESSAGES_SECONDS = 0.8

# Grace period for the agent task to drain remaining events
# (notably SessionEndedInputEvent) before being cancelled on shutdown.
AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS = 30.0

# Interrupted deliveries normally settle within milliseconds. A stuck delivery
# (e.g. a hung TTS websocket) must not keep the user's next turn waiting.
RESUME_RESPONSE_DELIVERY_TIMEOUT_SECONDS = 2.0


