class VoiceOutputChannel(OutputChannel):
    def __init__(
        self,
        voice_websocket: Websocket,
        tts_engine: TTSEngine,
        tts_cache: TTSCache,
        audio_format: AudioFormat,
        min_buffer_size: int = 0,
        min_delay_between_bot_messages_seconds: float = (
            DEFAULT_MIN_DELAY_BETWEEN_BOT_MESSAGES_SECONDS
        ),
        min_delay_after_filler_seconds: float = (
            DEFAULT_MIN_DELAY_AFTER_FILLER_BOT_MESSAGES_SECONDS
        ),
    ):
        super().__init__()
        self.voice_websocket = voice_websocket
        self.tts_engine = tts_engine
        self.tts_cache = tts_cache
        self.min_buffer_size = min_buffer_size
        self.audio_format = audio_format
        self.min_delay_between_bot_messages_seconds = (
            min_delay_between_bot_messages_seconds
        )
        self.min_delay_after_filler_seconds = min_delay_after_filler_seconds

        self.latest_message_id: Optional[str] = None

        self.input_queue: Optional[ConversationQueue[VoiceInputEvent]] = None

        # For streaming responses - background task that sends TTS audio
        self.audio_sender_task: Optional[asyncio.Task] = None
        self.tts_response: Optional[TTSResponse] = None

        # When the last bot message ended (streaming or non-streaming). Used to
        # enforce a minimum pacing gap before the next bot message.
        self._last_bot_message_end_time: Optional[float] = None

        # Set by ReAct agents after each streamed LLM reply (see OutputChannel hook).
        # Queued responses capture this when they are opened so later replies
        # cannot change the pacing decision before delivery starts.
        self._last_completed_bot_message_was_filler: bool = False

        self.stream_interrupted = False
        self._interrupt_playback: Optional[Callable[[], Awaitable[None]]] = None
        self.recording_session: Optional[CallRecordingSession] = None
        self.background_audio: Optional[BackgroundAudioPlayer] = None

        # Correlation id + delivery outcome tie logs across one utterance and
        # distinguish its diagnostic state from stale timing data.
        self._utterance_id: Optional[str] = None
        self._utterance_outcome: Optional[str] = None
        # TODO (VO-941): Group current utterance state to avoid
        #            missed resets.
        #            https://rasahq.atlassian.net/browse/VO-941
        self._current_response_audio_duration_ms: Optional[int] = None
        # Full text of a non-streamed message; streamed ones use the text sent to
        # TTS so far instead (see `_bot_text_for_markers`).
        self._current_response_text: Optional[str] = None
        self._current_response_event_id: Optional[str] = None

    def note_last_streamed_bot_message_was_filler(self, was_filler: bool) -> None:
        """Store filler classification for the next inter-message pacing decision."""
        self._last_completed_bot_message_was_filler = was_filler

    def set_interrupt_playback(
        self, interrupt_playback: Callable[[], Awaitable[None]]
    ) -> None:
        """Configure the transport-specific callback that clears buffered audio."""
        self._interrupt_playback = interrupt_playback

    async def interrupt_response(self) -> None:
        """Stop TTS generation, drop queued responses and clear buffered audio."""
        interruption = self.tts_engine.interrupt()
        self.interrupt_response_deliveries()
        if self.recording_session is not None:
            self.recording_session.mark_bot_playback_stopped()
        if self._interrupt_playback is not None:
            await self._interrupt_playback()
            if self.background_audio is not None:
                self.background_audio.playback_cleared()
        await interruption

    async def resume_response(self) -> None:
        """Hand the floor back to the bot once the user's input is taken in.

        An accepted barge-in gives the user the floor, and responses are withheld
        while producers keep running. Interrupted deliveries settle first, so none
        of them resumes once responses are allowed again. The wait is capped, so a
        stuck delivery cannot hold the floor or the turn indefinitely.
        """
        if call_state.user_has_floor:
            try:
                await asyncio.wait_for(
                    self.wait_for_response_deliveries(),
                    timeout=RESUME_RESPONSE_DELIVERY_TIMEOUT_SECONDS,
                )
            except asyncio.TimeoutError:
                logger.warning(
                    "voice_channel.resume_response.delivery_wait_timed_out",
                    timeout_seconds=RESUME_RESPONSE_DELIVERY_TIMEOUT_SECONDS,
                )
        call_state.user_has_floor = False

    @property
    def supports_streaming(self) -> bool:
        """Whether this channel supports streaming responses."""
        return self.tts_engine.streaming_input

    @property
    def supports_response_writer(self) -> bool:
        """Deliver streamed responses independently of their LLM producer."""
        return True

    @property
    def is_response_interrupted(self) -> bool:
        """Whether new responses are withheld because the user has the floor."""
        return call_state.user_has_floor

    def open_response(self, recipient_id: Text, **kwargs: Any) -> ResponseWriter:
        """Queue a response with the pacing state from when it was generated."""
        kwargs["previous_response_was_filler"] = (
            self._last_completed_bot_message_was_filler
        )
        writer = super().open_response(recipient_id, **kwargs)
        if self.is_response_interrupted:
            writer.interrupt()
        return writer

    def rasa_audio_bytes_to_channel_bytes(
        self, rasa_audio_bytes: RasaAudioBytes
    ) -> bytes:
        """Turn rasa's audio byte format into the format for the channel."""
        raise NotImplementedError

    def channel_bytes_to_message(self, recipient_id: str, channel_bytes: bytes) -> str:
        """Wrap the bytes for the channel in the proper format."""
        raise NotImplementedError

    def create_marker_message(self, marker_input: MarkerInput) -> MarkerMessageOutput:
        """Create a marker message for a specific channel."""
        raise NotImplementedError

    async def send_marker_message(self, marker_input: MarkerInput) -> None:
        """Send a message that marks positions in the audio stream."""
        marker_message = self.create_marker_message(marker_input)
        await self._notify_marker_sent(marker_input, marker_message.message_id)
        await self._send_marker_message_via_websocket(
            marker_message.message_id, marker_message.message
        )

    async def _notify_marker_sent(
        self, marker_input: MarkerInput, marker_id: str
    ) -> None:
        """Put the sent playback marker onto the input queue.

        Every marker (start, intermediate, end) is emitted so the queue is a complete
        record; the playback tracking handler decides which to act on. Skipped before
        the input queue is wired up.
        """
        if self.input_queue is None:
            return
        metadata = dict(marker_input.metadata or {})
        if self._current_response_event_id is not None:
            metadata[RESPONSE_EVENT_ID_METADATA_KEY] = self._current_response_event_id
        if self._current_response_audio_duration_ms is not None:
            metadata[TOTAL_AUDIO_DURATION_MS_METADATA_KEY] = (
                self._current_response_audio_duration_ms
            )
        bot_text = self._bot_text_for_markers()
        if bot_text is not None:
            metadata[BOT_TEXT_METADATA_KEY] = bot_text
        await self.input_queue.put(
            PlaybackMarkerSentInputEvent(
                marker_id=marker_id,
                marker_type=marker_input.marker_type,
                position=marker_input.position,
                metadata=metadata or None,
            )
        )

    def _bot_text_for_markers(self) -> Optional[str]:
        """Return the text the user may be hearing, for barge-in detection.

        A streamed message has no text when its start marker is sent, so every
        marker carries the text sent to TTS so far; audio is generated from that
        text, so it always covers what has been played.
        """
        if self._current_response_text is not None:
            return self._current_response_text
        return self._accumulated_streaming_text.strip() or None

    async def _send_marker_message_via_websocket(
        self, mark_id: str, marker_message: str
    ) -> None:
        try:
            await self.voice_websocket.send(marker_message)
        except WebsocketClosed:
            call_state.connection_failed = True
        self.latest_message_id = mark_id

    async def send_start_marker(self, marker_input: MarkerInput) -> None:
        """Send a marker message before the first audio chunk."""
        # Default implementation uses the generic marker message
        await self.send_marker_message(marker_input)

    async def send_intermediate_marker(self, marker_input: MarkerInput) -> None:
        """Send a marker message during audio streaming."""
        await self.send_marker_message(marker_input)

    async def send_end_marker(self, marker_input: MarkerInput) -> None:
        """Send a marker message after the last audio chunk."""
        await self.send_marker_message(marker_input)

    def update_silence_timeout(self) -> None:
        """Updates the silence timeout for the session."""
        if self.tracker_state:
            call_state.silence_timeout = self.tracker_state["slots"][
                SILENCE_TIMEOUT_SLOT
            ]
            logger.debug(
                "voice_channel.silence_timeout_updated",
                silence_timeout=call_state.silence_timeout,
            )

    def get_current_language(self) -> Optional[str]:
        """Get the current language from the tracker state."""
        if self.tracker_state:
            return self.tracker_state["slots"].get(LANGUAGE_SLOT)
        return None

    async def send_text_with_buttons(
        self,
        recipient_id: str,
        text: str,
        buttons: List[Dict[str, Any]],
        **kwargs: Any,
    ) -> None:
        """Uses the concise button output format for voice channels."""
        await self.send_text_with_buttons_concise(recipient_id, text, buttons, **kwargs)

    async def send_image_url(
        self, recipient_id: str, image: str, **kwargs: Any
    ) -> None:
        logger.warning(
            "voice_channel.image_suppressed",
            reason="Images cannot be sent via voice channels.",
        )

    async def send_attachment(
        self, recipient_id: str, attachment: str, **kwargs: Any
    ) -> None:
        logger.warning(
            "voice_channel.attachment_suppressed",
            reason="Attachments cannot be sent via voice channels.",
        )

    async def send_custom_json(
        self, recipient_id: str, json_message: Dict[str, Any], **kwargs: Any
    ) -> None:
        """Suppress custom JSON on voice channels that cannot transport it.

        Concrete channels with a data-frame protocol can override this method.
        The voice default must not delegate to ``OutputChannel``, because that
        implementation serializes the payload as text and sends it to TTS.
        """
        logger.warning(
            "voice_channel.custom_json_suppressed",
            reason="Custom JSON cannot be sent via this voice channel.",
        )

    def _track_rasa_processing_latency(self) -> None:
        """Track Rasa processing latency for the current bot message.

        Only meaningful for the first bot message of a turn, where the window is opened
        on the final ASR transcript. Subsequent bot messages in the same turn produce no
        measurement.
        """
        if not call_state.rasa_processing_start_time:
            logger.debug(
                "voice_channel.rasa_processing_latency.skipped",
                reason="rasa_processing_start_time is not set",
            )
            return
        call_state.rasa_processing_latency_ms = (
            time.time() - call_state.rasa_processing_start_time
        ) * 1000
        logger.debug(
            "voice_channel.rasa_processing_latency",
            latency_ms=call_state.rasa_processing_latency_ms,
        )
        # Close the window; follow-up bot messages in the same turn will not have a
        # measurement since there is no reliable signal for when Rasa starts processing
        # the next action.
        call_state.rasa_processing_start_time = None
        logger.debug("voice_channel.rasa_processing_window.closed")

    def _reset_tts_timing(self) -> None:
        """Reset TTS timing so stale values from the previous response never leak."""
        call_state.tts_start_time = time.time()
        self._clear_tts_metrics()
        logger.debug(
            "voice_channel.tts_timing_reset",
            tts_start_time=call_state.tts_start_time,
        )

    def _clear_tts_metrics(self) -> None:
        """Clear the per-utterance TTS metric snapshot in ``call_state``."""
        call_state.tts_first_byte_latency_ms = None
        call_state.tts_complete_latency_ms = None

    def _track_tts_first_byte_latency(self) -> None:
        """Track and log TTS first byte latency."""
        if not call_state.tts_start_time:
            logger.debug(
                "voice_channel.tts_first_byte_latency.skipped",
                reason="tts_start_time is not set",
            )
            return
        call_state.tts_first_byte_latency_ms = (
            time.time() - call_state.tts_start_time
        ) * 1000
        # Track this message's TTS latency and the turn's first audible output.
        voice_tracing.get_current_synthesize_speech_recorder().record_first_audio()
        voice_tracing.record_turn_tts_first_byte()
        logger.debug(
            "voice_channel.tts_first_byte_latency",
            latency_ms=call_state.tts_first_byte_latency_ms,
        )

    def _track_tts_complete_latency(self) -> None:
        """Track and log TTS completion latency.

        No-op if already recorded (e.g. captured at barge-in time).
        """
        if (
            not call_state.tts_start_time
            or call_state.tts_complete_latency_ms is not None
        ):
            logger.debug(
                "voice_channel.tts_complete_latency.skipped",
                tts_start_time=call_state.tts_start_time,
                tts_complete_latency_ms=call_state.tts_complete_latency_ms,
            )
            return
        call_state.tts_complete_latency_ms = (
            time.time() - call_state.tts_start_time
        ) * 1000
        voice_tracing.get_current_synthesize_speech_recorder().record_complete()
        logger.debug(
            "voice_channel.tts_complete_latency",
            latency_ms=call_state.tts_complete_latency_ms,
        )

    async def _stream_tts(self, recipient_id: str, response: TTSResponse) -> None:
        """Background task: listens to TTS audio stream and sends to channel.

        This pulls audio from TTS and directly sends it to the channel.
        """
        await self._stream_audio_to_channel(
            recipient_id, response, tts_response=response
        )

    async def _synthesize_and_stream_tts(
        self, recipient_id: str, text: str
    ) -> Optional[RasaAudioBytes]:
        """Use producer/consumer pattern to send TTS audio and collect for caching.

        Returns the collected audio bytes for caching.
        """
        voice_tracing.get_current_synthesize_speech_recorder().record_request()
        try:
            audio_stream = self.tts_engine.synthesize(text)
        except TTSError as e:
            logger.error("voice_channel.tts_synthesis_error", error=str(e))
            voice_tracing.get_current_synthesize_speech_recorder().record_error(e)
            # TODO: add message that works without tts, e.g. loading from disc
            audio_stream = self.chunk_audio(generate_silence(self.audio_format))

        collected_audio = await self._stream_audio_to_channel(
            recipient_id, audio_stream
        )
        return collected_audio

    async def _send_cached_audio(
        self, recipient_id: str, cached_audio: RasaAudioBytes
    ) -> None:
        """Send cached audio directly to websocket."""
        await self._stream_audio_to_channel(
            recipient_id, self.chunk_audio(cached_audio)
        )

    async def _stream_audio_to_channel(
        self,
        recipient_id: str,
        audio_stream: AsyncIterator[RasaAudioBytes],
        track_latency: bool = True,
        tts_response: Optional[TTSResponse] = None,
    ) -> Optional[RasaAudioBytes]:
        """Send audio from an async iterator to the channel.

        Background audio, when configured, is mixed into every chunk and its
        idle sender resumes once the stream ends, is interrupted, or fails.
        See `_send_audio_stream` for how the audio is sent.
        """
        try:
            return await self._send_audio_stream(
                recipient_id,
                audio_stream,
                track_latency,
                tts_response,
            )
        finally:
            if self.background_audio is not None:
                self.background_audio.agent_finished_speaking()

    async def _send_audio_stream(
        self,
        recipient_id: str,
        audio_stream: AsyncIterator[RasaAudioBytes],
        track_latency: bool,
        tts_response: Optional[TTSResponse] = None,
    ) -> Optional[RasaAudioBytes]:
        """Send audio from an async iterator to the channel.

        This function:

        - records TTS first-byte latency when ``track_latency`` is enabled,
        - records playback events and delivered-audio totals,
        - buffers audio into efficient send sizes,
        - emits word or elapsed intermediate playback markers,
        - preserves complete L16 samples, and
        - returns the collected audio for caching.

        First-byte latency is recorded from the first generated chunk, even
        when playback is interrupted.
        """
        collected_audio = RasaAudioBytes(b"", format=self.audio_format)
        last_sent_offset = 0
        first_byte_received = False
        leftover_byte: bytes = b""
        suppression_logged = False
        marker_scheduler = MarkerScheduler()
        sent_audio_bytes = 0

        # A new utterance must play even if the caller is still mid-speech.
        # Barge-in drops remaining chunks mid-stream via TTSEngine.interrupt().
        self.tts_engine.stop_streaming_output_audio_chunks = False

        # Pacing silence is excluded from utterance timing and audio totals.
        synthesis_recorder = (
            voice_tracing.get_current_synthesize_speech_recorder()
            if track_latency
            else None
        )

        with voice_tracing.play_audio_span(enabled=track_latency) as playback_recorder:
            async for audio_chunk in audio_stream:
                collected_audio = collected_audio + audio_chunk
                if synthesis_recorder is not None:
                    synthesis_recorder.record_audio_chunk(len(audio_chunk))

                # Track first byte BEFORE the barge-in check so the metric
                # reflects when the TTS produced its first audio, even when we
                # drop the bytes.
                if track_latency and not first_byte_received:
                    self._track_tts_first_byte_latency()
                    first_byte_received = True

                if (
                    self.is_response_interrupted
                    or self.tts_engine.stop_streaming_output_audio_chunks
                ):
                    playback_recorder.record_interrupted()
                    if not suppression_logged:
                        # Capture partial duration at the moment we start
                        # dropping bytes
                        if track_latency:
                            self._track_tts_complete_latency()
                        self.stream_interrupted = True
                        logger.debug(
                            "voice_channel.audio_streaming_suppressed",
                            reason=(
                                "playback interrupted; TTS audio dropped but timings"
                                " still recorded for voice observability"
                            ),
                        )
                        suppression_logged = True
                    continue

                # Check if we have enough new bytes to send
                current_buffer_size = len(collected_audio) - last_sent_offset
                if current_buffer_size < self.min_buffer_size:
                    # Not enough new audio to send yet, continue accumulating
                    continue

                try:
                    # send only the new bytes since last sent offset
                    new_bytes = leftover_byte + collected_audio.data[last_sent_offset:]
                    leftover_byte = b""

                    # Ensure even byte length for L16 audio (2 bytes per sample)
                    if len(new_bytes) % 2 != 0:
                        leftover_byte = new_bytes[-1:]
                        new_bytes = new_bytes[:-1]

                    # Send if there are new bytes
                    if len(new_bytes) > 0:
                        window_start_bytes = sent_audio_bytes
                        await self._send_agent_audio_bytes(
                            recipient_id,
                            RasaAudioBytes(new_bytes, format=self.audio_format),
                        )
                        voice_tracing.record_call_output_audio(len(new_bytes))
                        playback_recorder.record_chunk_sent(len(new_bytes))
                        sent_audio_bytes += len(new_bytes)
                        last_sent_offset = len(collected_audio)
                        await self._send_scheduled_markers(
                            recipient_id,
                            marker_scheduler,
                            window_start_bytes,
                            sent_audio_bytes,
                            tts_response,
                        )
                    else:
                        last_sent_offset = len(collected_audio)
                except WebsocketClosed:
                    call_state.connection_failed = True
                    # Continue collecting for cache even if send fails

            # send any remaining bytes (including leftover)
            window_start_bytes = sent_audio_bytes
            final_bytes_sent = await self._send_remaining_bytes(
                recipient_id, collected_audio, last_sent_offset, leftover_byte
            )
            sent_audio_bytes += final_bytes_sent
            # Providers often emit the last word timestamps after the last
            # audio chunk. Drain them even when this flush sends no bytes.
            if final_bytes_sent or sent_audio_bytes:
                try:
                    await self._send_scheduled_markers(
                        recipient_id,
                        marker_scheduler,
                        window_start_bytes if final_bytes_sent else sent_audio_bytes,
                        sent_audio_bytes,
                        tts_response,
                    )
                except WebsocketClosed:
                    call_state.connection_failed = True

        return collected_audio

    async def _send_scheduled_markers(
        self,
        recipient_id: str,
        scheduler: MarkerScheduler,
        window_start_bytes: int,
        sent_audio_bytes: int,
        tts_response: Optional[TTSResponse],
    ) -> None:
        """Send playback markers that align with audio already sent."""
        timestamp_batches = (
            tts_response.drain_word_timestamps() if tts_response is not None else []
        )
        bytes_per_second = self.audio_format.bytes_per_second
        window_start_ms = round(window_start_bytes / bytes_per_second * 1000)
        sent_ms = round(sent_audio_bytes / bytes_per_second * 1000)
        for position in scheduler.after_audio_sent(
            window_start_ms,
            sent_ms,
            timestamp_batches,
        ):
            await self.send_intermediate_marker(
                MarkerInput(
                    recipient_id=recipient_id,
                    marker_type=MarkerType.INTERMEDIATE,
                    position=position,
                )
            )
            logger.debug(
                "voice_channel.intermediate_marker_sent", **position.as_metadata()
            )

    async def apply_pacing_delay(self, recipient_id: str, seconds: float) -> None:
        """Apply pacing delay by sending silence as audio (generic, all channels).

        Sends N seconds of silence on the same audio path as TTS to enforce
        a natural gap between consecutive bot utterances. No server sleep.
        """
        if seconds <= 0:
            return
        silence = generate_silence(self.audio_format, length_in_seconds=seconds)
        # Silence is not TTS output, so don't let it pollute the first-byte latency
        # metric (would otherwise record the pacing wait as TTS latency).
        await self._stream_audio_to_channel(
            recipient_id, self.chunk_audio(silence), track_latency=False
        )

    async def _apply_min_delay_between_messages(
        self,
        recipient_id: str,
        previous_response_was_filler: Optional[bool] = None,
    ) -> None:
        """Enforce minimum delay between consecutive bot messages.

        Uses a longer gap after a filler message (see
        :meth:`note_last_streamed_bot_message_was_filler`) and a shorter gap
        between other consecutive utterances. Resets ``_last_bot_message_end_time``.
        """
        was_filler = (
            self._last_completed_bot_message_was_filler
            if previous_response_was_filler is None
            else previous_response_was_filler
        )
        min_gap_seconds = (
            self.min_delay_after_filler_seconds
            if was_filler
            else self.min_delay_between_bot_messages_seconds
        )
        if min_gap_seconds <= 0 or self._last_bot_message_end_time is None:
            self._last_bot_message_end_time = None
            return

        elapsed = time.monotonic() - self._last_bot_message_end_time
        wait_seconds = min_gap_seconds - elapsed
        if wait_seconds > 0:
            logger.debug(
                "voice_channel.apply_min_delay_between_messages",
                wait_seconds=wait_seconds,
                min_gap_seconds=min_gap_seconds,
                after_filler=was_filler,
            )
            await self.apply_pacing_delay(recipient_id, wait_seconds)
        self._last_bot_message_end_time = None

    async def _start_tts_message(
        self,
        recipient_id: str,
        previous_response_was_filler: Optional[bool] = None,
    ) -> None:
        """Prepare per-message TTS state at the start of a bot message.

        Records Rasa processing latency before pacing, applies any pacing
        delay, and initializes TTS timing, tracing, and interruption state for
        the utterance.

        Args:
            recipient_id: The recipient ID, forwarded to the pacing helper.
            previous_response_was_filler: Filler state captured when a queued
                response was opened. Non-queued sends use the latest state.
        """
        self._track_rasa_processing_latency()
        if previous_response_was_filler is None:
            await self._apply_min_delay_between_messages(recipient_id)
        else:
            await self._apply_min_delay_between_messages(
                recipient_id, previous_response_was_filler
            )
        # Initialize state after pacing so it covers only the spoken response.
        self._reset_tts_timing()
        voice_tracing.get_or_create_synthesize_speech_recorder(self.tts_engine)
        self.stream_interrupted = False
        self._current_response_audio_duration_ms = None
        self._current_response_text = None
        logger.debug("voice_channel.tts_message_started")

    async def _finish_tts_message(
        self,
        recipient_id: str,
    ) -> None:
        """Finalize per-message TTS state at the end of a bot message.

        Records TTS completion latency, sends the end marker, marks the end-of-message
        timestamp so the next message can pace correctly, and logs the per-message
        timing summary. Counterpart to `_start_tts_message`.

        Args:
            recipient_id: The recipient ID, used for the end marker and log entry.
        """
        self._track_tts_complete_latency()
        voice_tracing.get_current_synthesize_speech_recorder().end()
        await self.send_end_marker(
            MarkerInput(
                recipient_id=recipient_id,
                marker_type=MarkerType.END,
            )
        )
        self._last_bot_message_end_time = time.monotonic()
        logger.debug(
            "voice_channel.tts_message_ended",
            tts_first_byte_latency_ms=call_state.tts_first_byte_latency_ms,
            tts_complete_latency_ms=call_state.tts_complete_latency_ms,
            interrupted=self.stream_interrupted,
        )

    def _detach_audio_sender(self) -> Optional[asyncio.Task]:
        """Cancel the audio sender and hand it back, without awaiting it.

        Synchronous on purpose. The sender is a task of its own, so cancelling
        the turn never reaches it and this is the only place that stops it; on
        the interrupted path the caller may be killed at its next await, so the
        cancel must not sit behind one. Callers await the returned task
        separately, and losing that await only loses the confirmation.
        """
        task = self.audio_sender_task
        if task is None:
            return None
        self.audio_sender_task = None
        task.cancel()
        return task

    async def _send_remaining_bytes(
        self,
        recipient_id: str,
        collected_audio: RasaAudioBytes,
        last_sent_offset: int,
        leftover_byte: bytes,
    ) -> int:
        """Send remaining audio and return the number of bytes delivered."""
        if self.is_response_interrupted:
            return 0
        remaining_bytes = len(collected_audio) - last_sent_offset
        if remaining_bytes == 0 and len(leftover_byte) == 0:
            return 0

        try:
            new_bytes = leftover_byte + collected_audio.data[last_sent_offset:]
            # Pad with zero byte if odd length (final chunk)
            if len(new_bytes) % 2 != 0:
                new_bytes = new_bytes + b"\x00"
            if len(new_bytes) > 0:
                await self._send_agent_audio_bytes(
                    recipient_id,
                    RasaAudioBytes(new_bytes, format=self.audio_format),
                )
                voice_tracing.record_call_output_audio(len(new_bytes))
                voice_tracing.get_current_play_audio_recorder().record_chunk_sent(
                    len(new_bytes)
                )
                return len(new_bytes)
        except WebsocketClosed:
            # ignore sending error
            call_state.connection_failed = True
        return 0

    async def send_response_chunk_start(
        self, recipient_id: Text, **kwargs: Any
    ) -> None:
        """Start streaming response session.

        Starts background task (listens to TTS audio, sends to websocket).
        Enforces min delay since last bot message (pacing silence if needed).
        """
        await self._start_tts_message(
            recipient_id, kwargs.get("previous_response_was_filler")
        )
        self._current_response_event_id = kwargs.get(RESPONSE_EVENT_ID_METADATA_KEY)

        self.tts_engine.stream_state = StreamState.SENDING_RESPONSE_CHUNKS

        await super().send_response_chunk_start(recipient_id, **kwargs)

        if not self.tts_engine.streaming_input:
            return

        response = await self.tts_engine.start_response(
            streaming_config=kwargs.get("streaming_config")
        )

        if not self.tts_engine.streaming_input:
            await self.tts_engine.interrupt()
            return

        self.tts_response = response

        await self.send_start_marker(
            MarkerInput(
                recipient_id=recipient_id,
                marker_type=MarkerType.START,
            )
        )

        voice_tracing.get_current_synthesize_speech_recorder().record_request()
        self.audio_sender_task = asyncio.create_task(
            self._stream_tts(recipient_id, response)
        )
        logger.debug(
            "voice_channel.start_streaming_response",
            streaming_input=self.tts_engine.streaming_input,
        )

    async def send_response_chunk(
        self, recipient_id: str, chunk: str, **kwargs: Any
    ) -> None:
        """Send text chunk to TTS.

        The TTS engine will process this and the background consumer task
        will receive the audio and send it to the websocket.
        """
        if self.tts_engine.stream_state == StreamState.INTERRUPTED:
            self.stream_interrupted = True
            return

        if not self.tts_engine.streaming_input:
            return

        await super().send_response_chunk(recipient_id, chunk, **kwargs)
        voice_tracing.get_current_synthesize_speech_recorder().append_text(chunk)
        if self.tts_response is None:
            raise TTSError("No active TTS response")
        await self.tts_response.write(chunk)

    async def send_response_chunk_end(self, recipient_id: Text, **kwargs: Any) -> None:
        """End streaming response session.

        1. Flush TTS engine (process any remaining text) *or* interrupt it when
           the stream was aborted mid-utterance
        2. Wait for background task to finish sending all audio

        Args:
            recipient_id: The recipient ID.
            **kwargs: Additional arguments. Pass ``interrupted=True`` when the
                stream ended because of cancel/error so cleanup interrupts TTS
                instead of flushing a truncated fragment. Also treated as
                interrupted when ``tts_engine.stream_state`` is already
                ``INTERRUPTED`` (voice barge-in path).
        """
        await super().send_response_chunk_end(recipient_id, **kwargs)

        if not self.tts_engine.streaming_input:
            # fallback to non-streaming synthesis
            return

        interrupted = bool(kwargs.get("interrupted")) or (
            self.tts_engine.stream_state == StreamState.INTERRUPTED
        )
        response = self.tts_response
        self.tts_response = None
        if interrupted:
            self.stream_interrupted = True
            interruption = self.tts_engine.interrupt()
            sender = self._detach_audio_sender()
            await interruption
            if sender is not None:
                await asyncio.gather(sender, return_exceptions=True)
            self.tts_engine.stream_state = StreamState.NO_STREAMING
        else:
            if response is None:
                raise TTSError("No active TTS response")
            await response.finish()
            self.tts_engine.stream_state = StreamState.RESPONSE_CHUNKS_SENT

            if self.audio_sender_task:
                await self.audio_sender_task

            if self.tts_engine.stop_streaming_output_audio_chunks:
                self.stream_interrupted = True

            self.tts_engine.stream_state = StreamState.NO_STREAMING

        if self.stream_interrupted:
            logger.debug(
                "voice_channel.send_response_chunk_end.stream_interrupted",
            )

        await self._finish_tts_message(recipient_id)

    def send_text_message_awaits_playback(self) -> bool:
        """Wait for earlier audio, then synthesize and stream TTS.

        Subclasses inherit this. The intermediate send then uses a longer
        bound and leaves playback running if that bound is hit.
        """
        return True

    async def send_text_message(
        self, recipient_id: str, text: str, **kwargs: Any
    ) -> None:
        await self.wait_for_response_deliveries()
        if self.is_response_interrupted:
            return
        self._utterance_id = uuid.uuid4().hex[:8]
        logger.debug(
            "voice_channel.send_text_message",
            text=text,
            utterance_id=self._utterance_id,
        )

        await self._start_tts_message(recipient_id)
        self._current_response_event_id = kwargs.get(RESPONSE_EVENT_ID_METADATA_KEY)
        self.update_silence_timeout()

        # Check cache first
        cached_audio_bytes = self.tts_cache.get(text, self.audio_format)
        if isinstance(cached_audio_bytes, RasaAudioBytes):
            self._current_response_audio_duration_ms = int(
                cached_audio_bytes.full_seconds() * 1000
            )
        synthesis_recorder = voice_tracing.get_current_synthesize_speech_recorder()
        synthesis_recorder.record_text(text)
        logger.debug(
            "voice_channel.sending_audio",
            text=text,
            cached=bool(cached_audio_bytes),
            utterance_id=self._utterance_id,
        )

        self._current_response_text = text
        # Send start marker
        await self.send_start_marker(
            MarkerInput(
                recipient_id=recipient_id,
                marker_type=MarkerType.START,
            )
        )

        # Is the response interruptible?
        allow_interruptions = kwargs.get("allow_interruptions", True)
        call_state.channel_data["allow_interruptions"] = allow_interruptions

        if cached_audio_bytes:
            synthesis_recorder.record_cache_hit(True)
            await self._send_cached_audio(recipient_id, cached_audio_bytes)
            self._utterance_outcome = "sent:cached"
        else:
            synthesis_recorder.record_cache_hit(False)
            collected_audio = await self._synthesize_and_stream_tts(recipient_id, text)
            if collected_audio:
                self.tts_cache.put(text, collected_audio)
                self._utterance_outcome = "sent"
            elif self.stream_interrupted:
                self._utterance_outcome = "interrupted"
            else:
                # Watchdog: the bot decided to speak, nothing prevented it, yet
                # TTS produced zero audio — the user heard silence. Self-report
                # instead of failing silently.
                self._utterance_outcome = "audio_missing"
                logger.warning(
                    "voice_channel.audio_missing",
                    text=text,
                    utterance_id=self._utterance_id,
                    reason="tts_produced_no_audio_without_barge_in",
                )

        await self._finish_tts_message(recipient_id)

    async def send_audio_bytes(
        self, recipient_id: str, audio_bytes: RasaAudioBytes
    ) -> None:
        if self.is_response_interrupted:
            return
        if self.recording_session is not None:
            self.recording_session.record_bot_audio(audio_bytes)
        channel_bytes = self.rasa_audio_bytes_to_channel_bytes(audio_bytes)
        message = self.channel_bytes_to_message(recipient_id, channel_bytes)
        await self.voice_websocket.send(message)

    async def send_background_audio_bytes(
        self, recipient_id: str, audio_bytes: RasaAudioBytes
    ) -> None:
        """Send background audio played while the agent is silent."""
        try:
            await self.send_audio_bytes(recipient_id, audio_bytes)
        except (WebsocketClosed, websockets.exceptions.ConnectionClosed):
            call_state.connection_failed = True

    async def _send_agent_audio_bytes(
        self, recipient_id: str, audio_bytes: RasaAudioBytes
    ) -> None:
        """Send agent audio, with the background audio mixed in if configured."""
        if self.background_audio is not None:
            audio_bytes = self.background_audio.mix_into(audio_bytes)
        await self.send_audio_bytes(recipient_id, audio_bytes)

    async def chunk_audio(
        self, audio_bytes: RasaAudioBytes, chunk_size: int = 2048
    ) -> AsyncIterator[RasaAudioBytes]:
        """Generate chunks from cached audio bytes."""
        offset = 0
        while offset < len(audio_bytes):
            chunk = audio_bytes[offset : offset + chunk_size]
            if len(chunk):
                yield chunk
            offset += chunk_size
        return

    async def hangup(self, recipient_id: str, **kwargs: Any) -> None:
        voice_tracing.get_current_call_root_span().record_hangup_requested()
        call_state.hangup_requested = True

    async def send_turn_end_marker(self, recipient_id: str) -> None:
        """Send a marker to indicate the bot has finished its turn.

        Used internally by Rasa during conversation simulations.
        This is called after all bot messages in a turn have been sent.
        """
        pass


class VoiceLanguageChangePlugin:
    """Plugin that notifies ASR and TTS engines when the language slot changes.

    Registered per call in `run_audio_streaming` so each instance is tied to
    a specific sender and its own ASR/TTS engine pair.
    """

    def __init__(
        self, sender_id: str, asr_engine: ASREngine, tts_engine: TTSEngine
    ) -> None:
        self.sender_id = sender_id
        self.asr_engine = asr_engine
        self.tts_engine = tts_engine

    # Lifecycle methods
    def register_hook(self) -> None:
        """Register tasks for language change handling."""
        pm = plugin_manager()
        pm.register(self)

    async def unregister_hook(self) -> None:
        """Unregister tasks for language change handling."""
        pm = plugin_manager()
        pm.unregister(self)

    # hook implementation
    @hookimpl
    def after_action_executed(
        self, tracker: "DialogueStateTracker"
    ) -> Optional[Awaitable[None]]:
        """Check for language slot changes and notify ASR and TTS engines."""
        if tracker.sender_id != self.sender_id:
            return None

        language_slot = tracker.slots.get(LANGUAGE_SLOT)
        if not language_slot or not language_slot.value:
            # language slot is not set - this shouldn't be the case but
            # we don't want to update ASR / TTS engines in this case
            return None

        # This hook is sync, so return an awaitable and let the processor
        # await it before running side effects (e.g. TTS synthesis).
        return self.update_language(language_slot.value)

    async def update_language(self, new_language: str) -> None:
        """Update the language slot and notify ASR and TTS engines."""
        # Hook callbacks can run from non-voice channel contexts where `_call_state`
        # is unbound. Accessing `call_state` via LocalProxy in that case raises.
        current_call_state = _call_state.get(None)
        old_language = (
            current_call_state.current_language if current_call_state else None
        )

        if new_language == old_language:
            # language slot has not changed - no need to update ASR / TTS engines
            return

        logger.debug(
            "voice_channel.language_changed_after_action",
            old_language=old_language,
            new_language=new_language,
        )

        if current_call_state is not None:
            current_call_state.current_language = new_language

        await self.asr_engine.set_language(new_language)
        await self.tts_engine.set_language(new_language)


class VoiceInputChannel(InputChannel):
    # All children of this class require a voice license to be used.
    requires_voice_license = True

    def __init__(
        self,
        server_url: str,
        asr_config: Dict,
        tts_config: Dict,
        interruptions: Optional[Dict[str, Any]] = None,
        background_audio: Optional[Dict[str, Any]] = None,
        pause_after_filler: Optional[float] = None,
        pause_between_messages: Optional[float] = None,
    ):
        if self.requires_voice_license:
            validate_voice_license_scope()

        self.audio_format = MULAW_8KHZ
        self.server_url = server_url
        self.asr_config = asr_config
        self.tts_config = tts_config
        self.tts_cache = TTSCache(tts_config.get("cache_size", 1000))
        self.interruption_config = (
            InterruptionConfig(**interruptions)
            if interruptions
            else InterruptionConfig()
        )
        self.silence_timeout: Optional[float] = None
        if self.interruption_config.enabled:
            mark_as_beta_feature(f"Interruption Handling in {self.name()}")
            backchannel.warm_up()
        background_audio_config = parse_background_audio_config(background_audio)
        self.background_audio_source = (
            BackgroundAudioSource(background_audio_config)
            if background_audio_config
            else None
        )
        self.pause_after_filler = parse_pause_after_filler(pause_after_filler)
        self.pause_between_messages = parse_pause_between_messages(
            pause_between_messages
        )

        logger.info(
            "voice_channel.initialized",
            name=self.name(),
            server_url=self.server_url,
            asr_config=self.asr_config,
            tts_config=self.tts_config,
            interruption_config=self.interruption_config,
            background_audio_config=background_audio_config,
            pause_after_filler=self.pause_after_filler,
            pause_between_messages=self.pause_between_messages,
        )

    def get_sender_id(self, call_parameters: CallParameters) -> str:
        """Get the sender ID for the channel."""
        return call_parameters.call_id

    @classmethod
    def validate_basic_credentials(cls, credentials: Optional[Dict[str, Any]]) -> None:
        """Validate the basic credentials for the voice channel."""
        if not credentials:
            cls.raise_missing_credentials_exception()
        if not isinstance(credentials, dict):
            raise InvalidConfigException(
                "Credentials must be a dictionary for voice channel."
            )

        required_keys = {"server_url", "asr", "tts"}
        credentials_keys = set(credentials.keys())
        if not required_keys.issubset(credentials_keys):
            missing_fields = required_keys - credentials_keys
            raise InvalidConfigException(
                f"Missing required fields in credentials: {', '.join(missing_fields)} "
                f"for channel {cls.name()}"
            )

    @classmethod
    def from_credentials(
        cls, credentials: Optional[Dict[str, Any]]
    ) -> VoiceInputChannel:
        raise NotImplementedError

    def channel_bytes_to_rasa_audio_bytes(self, input_bytes: bytes) -> RasaAudioBytes:
        raise NotImplementedError

    async def collect_call_parameters(
        self,
        channel_websocket: Websocket,
        request: Optional[Any] = None,
    ) -> Optional[CallParameters]:
        raise NotImplementedError

    def build_turn_metadata(self, call_parameters: CallParameters) -> Dict[str, Any]:
        """Builds the metadata stamped onto a user turn.

        Every voice turn carries the call parameters collected at connect time
        so custom actions can read them from `tracker.latest_message["metadata"]`.

        Args:
            call_parameters: The call parameters collected when the call began.

        Returns:
            The call parameters as a dict.
        """
        return asdict(call_parameters)

    async def start_session(
        self,
        input_queue: ConversationQueue[VoiceInputEvent],
        call_parameters: CallParameters,
        recording_metadata: Optional[Dict[str, Any]] = None,
    ) -> None:
        """Start a voice session by enqueuing a SessionStartedInputEvent."""
        metadata = self.build_turn_metadata(call_parameters)
        if recording_metadata is not None:
            metadata["recording"] = recording_metadata
        event = SessionStartedInputEvent(
            metadata=metadata,
        )
        await input_queue.put(event)

    async def map_input_message(
        self,
        message: Any,
        ws: Websocket,
    ) -> VoiceChannelAction:
        """Map a channel input message to a voice channel action."""
        raise NotImplementedError

    async def interrupt_playback(
        self, ws: Websocket, call_parameters: CallParameters
    ) -> None:
        """Interrupt the current playback of audio.

        This function is used for interruption handling.
        As not all channels support flushing bot audio buffer,
        if a channel does not implement it. It has no effect.
        """
        pass

    async def receive_asr_events(
        self,
        asr_engine: ASREngine,
        tts_engine: TTSEngine,
        ws: Websocket,
        call_parameters: CallParameters,
        input_queue: ConversationQueue[VoiceInputEvent],
        agent: Optional[RuntimeAgent] = None,
        sender_id: Optional[str] = None,
    ) -> None:
        """Forward every ASR event from the engine onto the input queue."""
        try:
            async for event in asr_engine.stream_asr_events():
                logger.debug("voice_channel.receive_asr_events", ev=event)
                voice_tracing.trace_asr_event(event, asr_engine)
                await self.handle_asr_event(
                    event,
                    input_queue,
                    call_parameters,
                )
        except Exception as e:
            logger.error(
                "voice_channel.receive_asr_events.error",
                call_id=call_parameters.call_id,
                error=repr(e),
            )
            # Close the active transcription span as failed before re-raising.
            voice_tracing.get_current_transcribe_audio_recorder().record_error(e).end()
            raise
        finally:
            # Close an unfinished transcription span during stream teardown.
            voice_tracing.get_current_transcribe_audio_recorder().end()

    async def asr_keep_alive_task(self, asr_engine: ASREngine) -> None:
        interval = getattr(asr_engine.config, "keep_alive_interval", 5)
        while True:
            await asyncio.sleep(interval)
            await asr_engine.send_keep_alive()

    def _initialize_call_state(
        self,
        model_metadata: Optional["ModelMetadata"],
        agent_silence_timeout: Optional[float] = None,
    ) -> None:
        call_state_ = CallState(
            interruption_config=self.interruption_config,
            silence_timeout=resolve_call_silence_timeout(
                self.silence_timeout, agent_silence_timeout
            ),
        )
        call_state_.current_language = (
            model_metadata.language
            if model_metadata and model_metadata.language
            else "en"
        )
        _call_state.set(call_state_)

    def _get_asr_and_tts_engines(
        self, model_metadata: Optional["ModelMetadata"]
    ) -> Tuple[ASREngine, TTSEngine]:
        language = (
            model_metadata.language
            if model_metadata and model_metadata.language
            else "en"
        )
        additional_languages = (
            model_metadata.additional_languages if model_metadata else None
        )
        asr_engine = asr_engine_from_config(
            asr_config=self.asr_config,
            format=self.audio_format,
            language=language,
            additional_languages=additional_languages,
        )
        tts_engine = tts_engine_from_config(
            tts_config=self.tts_config,
            format=self.audio_format,
            language=language,
            additional_languages=additional_languages,
        )
        return asr_engine, tts_engine

    async def _create_background_audio_player(
        self,
    ) -> Optional[BackgroundAudioPlayer]:
        """Returns this call's background audio player, if one is configured."""
        if self.background_audio_source is None:
            return None
        track = await self.background_audio_source.create_track(
            self.audio_format.sample_rate
        )
        if track is None:
            return None
        return BackgroundAudioPlayer(track, self.audio_format)

    def _call_span_attributes(self) -> Dict[str, Any]:
        """Return non-sensitive channel, provider, and locale attributes."""
        attributes: Dict[str, Any] = {voice_semconv.VOICE_CHANNEL_NAME: self.name()}
        asr_provider = self.asr_config.get("name")
        if asr_provider:
            attributes[voice_semconv.VOICE_ASR_PROVIDER] = str(asr_provider)
        tts_provider = self.tts_config.get("name")
        if tts_provider:
            attributes[voice_semconv.VOICE_TTS_PROVIDER] = str(tts_provider)
        if call_state.current_language:
            attributes[voice_semconv.VOICE_LOCALE] = call_state.current_language
        return attributes

    async def run_audio_streaming(
        self,
        agent: RuntimeAgent,
        channel_websocket: Websocket,
        request: Optional[Any] = None,
    ) -> None:
        """Pipe input audio to ASR and consume ASR events simultaneously."""
        # Call parameters
        model_metadata = agent.model_metadata
        self._initialize_call_state(model_metadata, agent.voice_silence_timeout)

        call_parameters = await self.collect_call_parameters(channel_websocket, request)
        if call_parameters is None:
            raise ValueError("Failed to extract call parameters for call.")

        sender_id = self.get_sender_id(call_parameters)
        with conversation_log_context(sender_id):
            recording_session = create_call_recording_session(
                config=agent.recording_config,
                conversation_id=sender_id,
                call_parameters=call_parameters,
                audio_format=self.audio_format,
            )

            # Open the root span for this streaming session.
            with voice_tracing.voice_call_span(
                call_id=call_parameters.call_id,
                conversation_id=sender_id,
                attributes=self._call_span_attributes(),
            ):
                await self._run_audio_streaming_session(
                    agent,
                    channel_websocket,
                    model_metadata,
                    call_parameters,
                    sender_id,
                    recording_session,
                )

    async def _run_audio_streaming_session(
        self,
        agent: RuntimeAgent,
        channel_websocket: Websocket,
        model_metadata: Optional["ModelMetadata"],
        call_parameters: CallParameters,
        sender_id: str,
        recording_session: Optional[CallRecordingSession] = None,
    ) -> None:
        """Run streaming tasks and teardown for one call."""
        # Media engines (ASR/TTS)
        asr_engine, tts_engine = self._get_asr_and_tts_engines(model_metadata)
        async with asr_engine, tts_engine:
            try:
                # Session plumbing
                input_queue: ConversationQueue[VoiceInputEvent] = (
                    InMemoryConversationQueue[VoiceInputEvent](
                        conversation_id=sender_id,
                        input_channel=self.name(),
                        maxsize=50,
                    )
                )
                logger.info(
                    "voice_channel.input_queue_created",
                    conversation_id=sender_id,
                    call_id=call_parameters.call_id,
                )
                output_channel = self.create_output_channel(
                    channel_websocket, tts_engine
                )
                output_channel.min_delay_after_filler_seconds = self.pause_after_filler
                output_channel.min_delay_between_bot_messages_seconds = (
                    self.pause_between_messages
                )
                output_channel.recording_session = recording_session
                output_channel.input_queue = input_queue
                output_channel.set_interrupt_playback(
                    lambda: self.interrupt_playback(channel_websocket, call_parameters)
                )
                output_channel.background_audio = (
                    await self._create_background_audio_player()
                )
                language_plugin = VoiceLanguageChangePlugin(
                    sender_id, asr_engine, tts_engine
                )

                # Concurrent streaming. `agent_task` is kept separate from
                # `io_tasks` so shutdown can await it (not only cancel it) and
                # let session-end events finish.
                agent_task: Optional[asyncio.Task[Any]] = None
                io_tasks: List[asyncio.Task[Any]] = []

                try:
                    language_plugin.register_hook()
                    if output_channel.background_audio is not None:
                        output_channel.background_audio.start(
                            lambda chunk: output_channel.send_background_audio_bytes(
                                sender_id, chunk
                            ),
                        )

                    channel_controller = VoiceChannelController(
                        input_channel=self,
                        input_queue=input_queue,
                        call_parameters=call_parameters,
                    )

                    # Start the agent conversation handler
                    agent_task = asyncio.create_task(
                        agent.handle_conversation(
                            input_queue,
                            output_channel,
                            channel_controller,
                        )
                    )

                    # Send session start event
                    await self.start_session(
                        input_queue,
                        call_parameters,
                        recording_session.started_metadata
                        if recording_session
                        else None,
                    )
                    voice_tracing.get_current_call_root_span().record_call_started()

                    io_tasks = [
                        asyncio.create_task(
                            self._consume_audio_bytes(
                                channel_websocket,
                                asr_engine,
                                input_queue,
                                call_parameters,
                                recording_session,
                            ),
                            name="caller_audio",
                        ),
                        asyncio.create_task(
                            self.receive_asr_events(
                                asr_engine,
                                tts_engine,
                                channel_websocket,
                                call_parameters,
                                input_queue,
                                agent,
                                sender_id,
                            ),
                            name="asr_receive",
                        ),
                        asyncio.create_task(
                            self.asr_keep_alive_task(asr_engine),
                            name="asr_keep_alive",
                        ),
                    ]
                    # Include agent_task so a crash in the agent also unblocks
                    # the wait and triggers cleanup.
                    done, _ = await asyncio.wait(
                        [*io_tasks, agent_task],
                        return_when=asyncio.FIRST_COMPLETED,
                    )
                    io_task_set = set(io_tasks)
                    for task in done:
                        if task not in io_task_set:
                            continue
                        task_name = task.get_name()
                        exception = None if task.cancelled() else task.exception()
                        if exception is not None:
                            logger.error(
                                "voice_channel.streaming_task_failed",
                                call_id=call_parameters.call_id,
                                task=task_name,
                                exception_type=type(exception).__name__,
                            )
                        elif task_name != "caller_audio" or task.cancelled():
                            logger.warning(
                                "voice_channel.streaming_task_ended_unexpectedly",
                                call_id=call_parameters.call_id,
                                task=task_name,
                            )
                finally:
                    # Marked before the shutdown grace period so the recording ends at
                    # the moment the call dropped, not when the agent finishes shutting
                    # down.
                    if recording_session is not None:
                        recording_session.mark_call_ended()
                    voice_tracing.get_current_call_root_span().record_call_ended()
                    if output_channel.background_audio is not None:
                        await output_channel.background_audio.stop()
                    # Stop I/O before waiting for the agent. Cancelling the read
                    # loop still signals session end so the agent can finish.
                    for task in io_tasks:
                        task.cancel()
                    if io_tasks:
                        await asyncio.gather(*io_tasks, return_exceptions=True)
                        for task in io_tasks:
                            voice_tracing.get_current_call_root_span().check_and_record_task_failure(
                                task
                            )

                    # Give the agent a grace period to finish pending work (e.g.
                    # session end) before the engines are closed. Cancels the
                    # task if it hangs.
                    if agent_task is not None:
                        await self._await_agent_shutdown(agent_task, call_parameters)
                        voice_tracing.get_current_call_root_span().check_and_record_task_failure(
                            agent_task
                        )

                    if isinstance(output_channel, OutputChannel):
                        await output_channel.shutdown_response_deliveries()

                    # Unregister the language-change hook before the surrounding
                    # ``async with`` closes the ASR/TTS connections.
                    await language_plugin.unregister_hook()
            finally:
                await channel_websocket.close()
                if recording_session is not None:
                    recording_session.finalize()

    async def _consume_audio_bytes(
        self,
        channel_websocket: Websocket,
        asr_engine: ASREngine,
        input_queue: ConversationQueue[VoiceInputEvent],
        call_parameters: CallParameters,
        recording_session: Optional[CallRecordingSession] = None,
    ) -> None:
        """Read audio frames from the websocket and route them to ASR or the queue.

        Always enqueue a SessionEndedInputEvent when input ends or teardown
        cancels the task. Cancellation does not record a remote disconnect.
        """
        is_disconnected = False
        # Timestamp used only when recording a message-handling failure.
        operation_started_ns = time.time_ns()
        try:
            async for message in channel_websocket:
                operation_started_ns = time.time_ns()
                channel_action = await self.map_input_message(
                    message, channel_websocket
                )

                if isinstance(channel_action, NewAudioAction):
                    if recording_session is not None:
                        recording_session.record_user_audio(channel_action.audio_bytes)
                    voice_tracing.record_call_input_audio(
                        len(channel_action.audio_bytes)
                    )
                    try:
                        await asr_engine.send_audio_chunks(channel_action.audio_bytes)
                    except (
                        websockets.exceptions.ConnectionClosedOK,
                        websockets.exceptions.ConnectionClosedError,
                    ) as e:
                        # Defense in depth for ASR subclasses that don't swallow
                        # ConnectionClosed* internally (the base ASREngine does).
                        # Dropping the chunk avoids tearing down the call task.
                        logger.debug(
                            "voice_channel.audio_streaming."
                            "asr_connection_closed_drop_chunk",
                            error=str(e),
                        )
                        continue
                if isinstance(channel_action, TextInputAction):
                    self._mark_rasa_processing_started()
                    await input_queue.put(
                        FinalTranscriptInputEvent(
                            text=channel_action.text,
                            metadata=asdict(call_parameters),
                        )
                    )
                elif isinstance(channel_action, DTMFInputAction):
                    await input_queue.put(
                        DTMFKeypressInputEvent(
                            digit=channel_action.digit,
                            metadata=asdict(call_parameters),
                        )
                    )
                elif isinstance(channel_action, PlaybackMarkerAckAction):
                    await input_queue.put(
                        PlaybackMarkerAcknowledgedInputEvent(
                            marker_id=channel_action.marker_id,
                            metadata=asdict(call_parameters),
                        )
                    )
                elif isinstance(channel_action, BotPlaybackStartedAction):
                    await input_queue.put(
                        BotPlaybackStartedInputEvent(
                            metadata=asdict(call_parameters),
                        )
                    )
                elif isinstance(channel_action, BotPlaybackStoppedAction):
                    await input_queue.put(
                        BotPlaybackStoppedInputEvent(
                            metadata=asdict(call_parameters),
                        )
                    )
                elif isinstance(channel_action, EndConversationAction):
                    logger.info(
                        "voice_channel.end_conversation_received",
                        call_id=call_parameters.call_id,
                    )
                    is_disconnected = True
                    await self.handle_disconnect(input_queue, call_parameters)
                    break
        except asyncio.CancelledError:
            # The agent may still be waiting for input. Signal session end, but
            # do not record a remote disconnect because the peer did not hang up.
            if not is_disconnected:
                logger.debug(
                    "voice_channel.audio_input_cancelled",
                    call_id=call_parameters.call_id,
                )
                await input_queue.put(SessionEndedInputEvent())
            raise
        except Exception as e:
            logger.error("voice_channel.audio_streaming_error", error=str(e))
            voice_tracing.record_channel_message_failure(
                e, start_time_ns=operation_started_ns
            )
            # Let the agent shut down cleanly even when the read loop failed.
            await self.handle_disconnect(input_queue, call_parameters)
            raise e
        else:
            if not is_disconnected:
                logger.info(
                    "voice_channel.websocket_closed_by_remote",
                    call_id=call_parameters.call_id,
                )
                await self.handle_disconnect(input_queue, call_parameters)

    async def _await_agent_shutdown(
        self,
        agent_task: asyncio.Task[Any],
        call_parameters: CallParameters,
    ) -> None:
        """Wait for the agent task to shut down after I/O has stopped.

        Bounded by `AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS`. On timeout, the task is
        cancelled. Exceptions from the agent are logged and not re-raised so channel
        cleanup still runs.
        """
        if agent_task.done():
            if agent_task.cancelled():
                return
            if exc := agent_task.exception():
                logger.error(
                    "voice_channel.agent_task_failed",
                    event_info=(
                        "Agent task raised an exception before shutdown. "
                        "SessionEnded may not have been processed."
                    ),
                    call_id=call_parameters.call_id,
                    error=str(exc),
                )
            return

        try:
            # wait_for cancels agent_task on timeout and re-raises TimeoutError.
            await asyncio.wait_for(
                agent_task,
                timeout=AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS,
            )
            logger.debug(
                "voice_channel.agent_task_shutdown_completed",
                event_info=(
                    "Agent task finished within the "
                    f"{AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS} seconds grace period and "
                    "was not cancelled."
                ),
                call_id=call_parameters.call_id,
            )
        except asyncio.TimeoutError:
            logger.error(
                "voice_channel.agent_task_shutdown_timeout",
                event_info=(
                    "Agent task did not finish within the "
                    f"{AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS} seconds grace period and "
                    "was cancelled. SessionEnded may not have been processed."
                ),
                call_id=call_parameters.call_id,
                timeout_seconds=AGENT_SHUTDOWN_GRACE_PERIOD_SECONDS,
            )
        except Exception as e:
            logger.error(
                "voice_channel.agent_task_failed",
                event_info=(
                    "Agent task raised an exception during shutdown. "
                    "SessionEnded may not have been processed."
                ),
                call_id=call_parameters.call_id,
                error=str(e),
            )

    def create_output_channel(
        self,
        voice_websocket: Websocket,
        tts_engine: TTSEngine,
    ) -> VoiceOutputChannel:
        """Create a matching voice output channel for this voice input channel."""
        raise NotImplementedError

    def _mark_rasa_processing_started(self) -> None:
        """Open the Rasa-processing window for the first bot message of a turn."""
        call_state.rasa_processing_start_time = time.time()
        logger.debug(
            "voice_channel.rasa_processing_window.opened",
            rasa_processing_start_time=call_state.rasa_processing_start_time,
        )

    async def handle_asr_event(
        self,
        asr_event: ASREvent,
        input_queue: ConversationQueue[VoiceInputEvent],
        call_parameters: CallParameters,
    ) -> None:
        """Handle a new event from the ASR system."""
        if isinstance(asr_event, NewTranscript) and asr_event.text:
            logger.debug(
                "VoiceInputChannel.handle_asr_event.new_transcript",
                transcript=asr_event.text,
            )
            # Open the Rasa-processing window for the first bot message.
            self._mark_rasa_processing_started()

            event: VoiceInputEvent = FinalTranscriptInputEvent(
                text=asr_event.text,
                metadata=self.build_turn_metadata(call_parameters),
            )
            await input_queue.put(event)
        elif isinstance(asr_event, UserIsSpeaking):
            logger.debug(
                "VoiceInputChannel.handle_asr_event.partial_transcript",
                transcript=asr_event.text,
            )
            event = PartialTranscriptInputEvent(
                text=asr_event.text,
                metadata=asdict(call_parameters),
            )
            await input_queue.put(event)

    async def handle_disconnect(
        self,
        input_queue: ConversationQueue[VoiceInputEvent],
        call_parameters: CallParameters,
    ) -> None:
        """Handle disconnection from the channel."""
        voice_tracing.get_current_call_root_span().record_disconnect()
        event = SessionEndedInputEvent()
        await input_queue.put(event)
